//! Generates a save fixture from a scripted game, for migration testing.
//! The committed fixture at tests/fixtures/save_v1.json was generated by this
//! script at save_version 1; re-running it produces the *current* version, so
//! never overwrite an old fixture — each version's fixture is a historical
//! artifact.

use clowder_core::*;

fn main() {
    let mut s = GameState::new(20260705);
    // A small played meadow: gathers, a patch, a cushion, two kittens, a job.
    for _ in 0..30 {
        let _ = s.apply(Command::GatherCatnip);
    }
    let _ = s.apply(Command::Build(StructureId::CatnipPatch));
    s.resources[ResourceId::Catnip.ix()] = 120.0;
    s.resources[ResourceId::Twigs.ix()] = 10.0;
    s.structures[StructureId::CozyCushion.ix()] += 2;
    s.structures[StructureId::CardboardBox.ix()] += 1;
    for _ in 0..2 {
        s.pity = 4;
        s.resources[ResourceId::Catnip.ix()] = s.resources[ResourceId::Catnip.ix()].max(100.0);
        for _ in 0..10 {
            s.tick();
        }
    }
    let _ = s.apply(Command::AssignJob(JobId::Gardener));
    for _ in 0..25 {
        s.tick();
    }
    println!("{}", save_string(&s, 1_751_700_000));
}
